using Aurora.AllocationEngine.Interfaces;
using Aurora.AllocationEngine.Models;
using Microsoft.Extensions.Logging;

namespace Aurora.AllocationEngine.Strategies;

public class ProRataAllocationStrategy : IAllocationStrategy
{
    private readonly ILogger<ProRataAllocationStrategy> _logger;

    public ProRataAllocationStrategy(ILogger<ProRataAllocationStrategy> logger)
    {
        _logger = logger;
    }

    public async Task<List<AllocationResult>> AllocateAsync(AllocationRequest request, CancellationToken cancellationToken = default)
    {
        _logger.LogInformation("Executing Pro-Rata allocation for trade {TradeRef}", request.Trade.TradeReference);

        var allocations = new List<AllocationResult>();

        // Get only funds that passed compliance
        var eligibleFunds = request.ComplianceResults.FundResults
            .Where(f => f.Passed)
            .ToList();

        if (!eligibleFunds.Any())
        {
            _logger.LogWarning("No eligible funds for allocation");
            return allocations;
        }

        // Calculate total available capacity across all funds
        var totalCapacity = eligibleFunds.Sum(f => Math.Min(f.AvailableCapacity, f.Fund.AvailableCash));

        if (totalCapacity == 0)
        {
            _logger.LogWarning("Total available capacity is zero");
            return allocations;
        }

        var totalToAllocate = Math.Min(request.Trade.TotalTradeAmount, totalCapacity);

        foreach (var fundResult in eligibleFunds)
        {
            var fund = fundResult.Fund;
            var effectiveCapacity = Math.Min(fundResult.AvailableCapacity, fund.AvailableCash);

            // Calculate pro-rata allocation based on capacity
            var allocationPercentage = effectiveCapacity / totalCapacity;
            var allocatedAmount = totalToAllocate * allocationPercentage;

            // Ensure we don't exceed fund capacity or available cash
            allocatedAmount = Math.Min(allocatedAmount, effectiveCapacity);

            if (allocatedAmount > 0)
            {
                allocations.Add(new AllocationResult
                {
                    Fund = fund,
                    AllocatedAmount = allocatedAmount,
                    AllocatedQuantity = allocatedAmount / request.Trade.Price,
                    AllocationPercentage = (allocatedAmount / request.Trade.TotalTradeAmount) * 100,
                    AvailableCapacity = fundResult.AvailableCapacity,
                    AllocationReason = $"Pro-Rata based on capacity ({allocationPercentage:P2})"
                });
            }
        }

        _logger.LogInformation("Pro-Rata allocation completed: {FundCount} funds, Total: {Total:C}",
            allocations.Count, allocations.Sum(a => a.AllocatedAmount));

        return await Task.FromResult(allocations);
    }
}

using Aurora.AllocationEngine.Interfaces;
using Aurora.AllocationEngine.Models;
using Microsoft.Extensions.Logging;

namespace Aurora.AllocationEngine.Strategies;

public class TargetedAllocationStrategy : IAllocationStrategy
{
    private readonly ILogger<TargetedAllocationStrategy> _logger;

    public TargetedAllocationStrategy(ILogger<TargetedAllocationStrategy> logger)
    {
        _logger = logger;
    }

    public async Task<List<AllocationResult>> AllocateAsync(AllocationRequest request, CancellationToken cancellationToken = default)
    {
        _logger.LogInformation("Executing Targeted allocation for trade {TradeRef}", request.Trade.TradeReference);

        var allocations = new List<AllocationResult>();

        // Get only funds that passed compliance
        var eligibleFunds = request.ComplianceResults.FundResults
            .Where(f => f.Passed)
            .OrderByDescending(f => f.AvailableCapacity) // Prioritize funds with highest capacity
            .ToList();

        if (!eligibleFunds.Any())
        {
            _logger.LogWarning("No eligible funds for allocation");
            return allocations;
        }

        var remainingAmount = request.Trade.TotalTradeAmount;

        foreach (var fundResult in eligibleFunds)
        {
            if (remainingAmount <= 0)
                break;

            var fund = fundResult.Fund;
            var effectiveCapacity = Math.Min(fundResult.AvailableCapacity, fund.AvailableCash);

            // Allocate as much as possible to this fund
            var allocatedAmount = Math.Min(remainingAmount, effectiveCapacity);

            if (allocatedAmount > 0)
            {
                allocations.Add(new AllocationResult
                {
                    Fund = fund,
                    AllocatedAmount = allocatedAmount,
                    AllocatedQuantity = allocatedAmount / request.Trade.Price,
                    AllocationPercentage = (allocatedAmount / request.Trade.TotalTradeAmount) * 100,
                    AvailableCapacity = fundResult.AvailableCapacity,
                    AllocationReason = $"Targeted allocation - filled to capacity"
                });

                remainingAmount -= allocatedAmount;
            }
        }

        _logger.LogInformation("Targeted allocation completed: {FundCount} funds, Total: {Total:C}, Remaining: {Remaining:C}",
            allocations.Count, allocations.Sum(a => a.AllocatedAmount), remainingAmount);

        return await Task.FromResult(allocations);
    }
}

using Aurora.AllocationEngine.Interfaces;
using Aurora.AllocationEngine.Models;
using Microsoft.Extensions.Logging;

namespace Aurora.AllocationEngine.Strategies;

public class CustomAllocationStrategy : IAllocationStrategy
{
    private readonly ILogger<CustomAllocationStrategy> _logger;

    public CustomAllocationStrategy(ILogger<CustomAllocationStrategy> logger)
    {
        _logger = logger;
    }

    public async Task<List<AllocationResult>> AllocateAsync(AllocationRequest request, CancellationToken cancellationToken = default)
    {
        _logger.LogInformation("Executing Custom allocation for trade {TradeRef}", request.Trade.TradeReference);

        var allocations = new List<AllocationResult>();

        if (request.CustomAllocations == null || !request.CustomAllocations.Any())
        {
            _logger.LogWarning("No custom allocations provided");
            return allocations;
        }

        // Match custom allocations with compliance results
        foreach (var customAlloc in request.CustomAllocations)
        {
            var fundResult = request.ComplianceResults.FundResults
                .FirstOrDefault(f => f.Fund.Id == customAlloc.FundId);

            if (fundResult == null)
            {
                _logger.LogWarning("Fund {FundId} not found in compliance results", customAlloc.FundId);
                continue;
            }

            if (!fundResult.Passed)
            {
                _logger.LogWarning("Fund {FundCode} failed compliance, skipping", fundResult.Fund.FundCode);
                continue;
            }

            var fund = fundResult.Fund;
            var effectiveCapacity = Math.Min(fundResult.AvailableCapacity, fund.AvailableCash);

            // Use target amount if specified, otherwise calculate from percentage
            var targetAmount = customAlloc.TargetAmount > 0
                ? customAlloc.TargetAmount
                : request.Trade.TotalTradeAmount * (customAlloc.TargetPercentage / 100m);

            // Ensure we don't exceed capacity
            var allocatedAmount = Math.Min(targetAmount, effectiveCapacity);

            if (allocatedAmount > 0)
            {
                allocations.Add(new AllocationResult
                {
                    Fund = fund,
                    AllocatedAmount = allocatedAmount,
                    AllocatedQuantity = allocatedAmount / request.Trade.Price,
                    AllocationPercentage = (allocatedAmount / request.Trade.TotalTradeAmount) * 100,
                    AvailableCapacity = fundResult.AvailableCapacity,
                    AllocationReason = $"Custom allocation (Target: {targetAmount:C}, Actual: {allocatedAmount:C})"
                });
            }
        }

        _logger.LogInformation("Custom allocation completed: {FundCount} funds, Total: {Total:C}",
            allocations.Count, allocations.Sum(a => a.AllocatedAmount));

        return await Task.FromResult(allocations);
    }
}

