using Aurora.Core.DTOs;
using Aurora.TradeBooking.Services;
using Microsoft.AspNetCore.Mvc;

namespace Aurora.API.Controllers;

[ApiController]
[Route("api/[controller]")]
[Produces("application/json")]
public class TradeController : ControllerBase
{
    private readonly TradeBookingService _tradeBookingService;
    private readonly ILogger<TradeController> _logger;

    public TradeController(TradeBookingService tradeBookingService, ILogger<TradeController> logger)
    {
        _tradeBookingService = tradeBookingService;
        _logger = logger;
    }

    /// <summary>
    /// Books a new trade with compliance checks and allocation
    /// </summary>
    /// <param name="request">Trade booking request</param>
    /// <param name="cancellationToken">Cancellation token</param>
    /// <returns>Trade booking response with compliance and allocation details</returns>
    [HttpPost("book")]
    [ProducesResponseType(typeof(TradeBookingResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status400BadRequest)]
    [ProducesResponseType(StatusCodes.Status500InternalServerError)]
    public async Task<ActionResult<TradeBookingResponse>> BookTrade(
        [FromBody] TradeBookingRequest request,
        CancellationToken cancellationToken)
    {
        try
        {
            _logger.LogInformation("Received trade booking request for {TradeRef}", request.TradeReference);

            var response = await _tradeBookingService.BookTradeAsync(request, cancellationToken);

            if (response.Success)
            {
                return Ok(response);
            }
            else
            {
                return BadRequest(response);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing trade booking request");
            return StatusCode(500, new
            {
                success = false,
                message = "An error occurred while processing the trade",
                error = ex.Message
            });
        }
    }
}

